_LAT1, _LON0, _K, _S = 55.44, -10.72, 0.5948227867513414, 98.03921568627455


def project(lat, lon):
    """(x, y) in the drawing's viewBox for a latitude and longitude."""
    return ((lon - _LON0) * _K * _S, (_LAT1 - lat) * _S)


